### 🚀 3. `script.js` (Comportamento)

```javascript
// 1. Pega os elementos do HTML
const searchInput = document.getElementById('searchInput');
const searchButton = document.getElementById('searchButton');
const resultText = document.getElementById('resultText');

// 2. Função que será executada ao clicar no botão ou apertar Enter
function handleSearch() {
    // Pega o valor digitado pelo usuário e remove espaços extras
    const searchTerm = searchInput.value.trim();

    if (searchTerm === "") {
        resultText.textContent = "Por favor, digite um termo de busca.";
        resultText.style.color = "orange";
        return; // Sai da função se o campo estiver vazio
    }

    // --- SIMULAÇÃO DE BUSCA ---
    // Em um projeto real, você faria uma chamada fetch() para uma API aqui.
    console.log(`Buscando por: ${searchTerm}`);

    // Simula o sucesso da busca
    resultText.textContent = `✅ Informações sobre "${searchTerm}" encontradas! (Isto é uma simulação. Para resultados reais, conecte a uma API.)`;
    resultText.style.color = "#28a745";
}

// 3. Adiciona o evento de clique ao botão
searchButton.addEventListener('click', handleSearch);

// 4. Adiciona o evento de pressionar "Enter" no campo de busca
searchInput.addEventListener('keypress', function(event) {
    // O código 13 corresponde à tecla Enter
    if (event.key === 'Enter') {
        handleSearch();
    }
});

console.log("Script de busca carregado com sucesso!");
```

